def transform(grid):
    h,w=len(grid),len(grid[0])
    candidates=[]
    for sign in (1,-1):  # r+c, c-r
        lines={}
        for r,row in enumerate(grid):
            for c,v in enumerate(row):
                if v:
                    k=r+c if sign==1 else c-r
                    lines.setdefault(k,set()).add(v)
        # use orientation with the fewest occupied diagonals; all line marks are complete
        candidates.append((len(lines),sign,lines))
    _,sign,lines=min(candidates,key=lambda x:x[0])
    marks={k:next(iter(vs)) for k,vs in lines.items()}
    period=None; cmap=None
    for p in range(1,max(h,w)*2+1):
        m={}
        ok=True
        for k,v in marks.items():
            residue=k%p
            if residue in m and m[residue]!=v:
                ok=False; break
            m[residue]=v
        if ok and len(m)==p:
            period,cmap=p,m; break
    if period is None:
        raise ValueError((marks,sign))
    return [[cmap[((r+c) if sign==1 else (c-r))%period] for c in range(w)] for r in range(h)]

