source='''def transform(grid):
    height, width = len(grid), len(grid[0])

    # The colored guide lines run in one of the two diagonal directions.
    choices = []
    for orientation in ("sum", "difference"):
        lines = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    key = r + c if orientation == "sum" else c - r
                    lines.setdefault(key, set()).add(color)
        choices.append((len(lines), orientation, lines))

    _, orientation, lines = min(choices, key=lambda item: item[0])
    marks = {key: next(iter(colors)) for key, colors in lines.items()}

    # Repeat the diagonal colors with the smallest period that covers every
    # residue and does not assign two colors to the same residue.
    period = None
    pattern = None
    for candidate in range(1, 2 * max(height, width) + 1):
        residues = {}
        for key, color in marks.items():
            residue = key % candidate
            if residue in residues and residues[residue] != color:
                break
            residues[residue] = color
        else:
            if len(residues) == candidate:
                period, pattern = candidate, residues
                break

    if period is None:
        raise ValueError("Could not infer a complete diagonal color period")

    return [
        [pattern[(r + c if orientation == "sum" else c - r) % period]
         for c in range(width)]
        for r in range(height)
    ]
